  // afterId: the card that will be ABOVE the moved card.
  // beforeId: the card that will be BELOW the moved card.

  try {
    const res = await fetch(`${API_BASE}/cards/${cardId}/move`, {
      method: 'PATCH',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        columnId: columnId,
