// SSE Setup
function setupSSE() {
  const eventSource = new EventSource(`${API_BASE}/stream`);

  eventSource.addEventListener('cardCreated', (e) => {
    const card = JSON.parse(e.data);
    const listEl = document.getElementById(`list-${card.column_id}`);
