  eventSource.addEventListener('cardMoved', (e) => {
    const card = JSON.parse(e.data);
    const listEl = document.getElementById(`list-${card.column_id}`);
    if (!listEl) return;

    const cardEl = document.getElementById(`card-${card.id}`);
