    const { rows: cardRows } = await db.query('SELECT * FROM cards WHERE id = $1', [id]);
    const updatedCard = cardRows[0];

    broadcast('cardMoved', updatedCard);
    res.json(updatedCard);
  } catch (err) {
    res.status(500).json({ error: err.message });
